Here are a few simple options (pick based on what runtime you want). Each generates **exactly 1 GiB (1,073,741,824 bytes)** of cryptographically-strong random data.

### Python (writes to a file, streaming)
```py
import os

ONE_GIB = 1024 * 1024 * 1024

def write_random_1gib(path: str, chunk_size: int = 8 * 1024 * 1024) -> None:
    remaining = ONE_GIB
    with open(path, "wb") as f:
        while remaining:
            n = min(chunk_size, remaining)
            f.write(os.urandom(n))
            remaining -= n
```

### Node.js (writes to a file, streaming)
```js
import { createWriteStream } from "node:fs";
import { randomBytes } from "node:crypto";

const ONE_GIB = 1024 * 1024 * 1024;

export async function writeRandom1GiB(path, chunkSize = 8 * 1024 * 1024) {
  await new Promise((resolve, reject) => {
    const out = createWriteStream(path);
    out.on("error", reject);
    out.on("finish", resolve);

    let remaining = ONE_GIB;
    while (remaining > 0) {
      const n = Math.min(chunkSize, remaining);
      out.write(randomBytes(n));
      remaining -= n;
    }
    out.end();
  });
}
```

### Go (writes to a file)
```go
package main

import (
	"crypto/rand"
	"io"
	"os"
)

const OneGiB int64 = 1024 * 1024 * 1024

func WriteRandom1GiB(path string) error {
	f, err := os.Create(path)
	if err != nil { return err }
	defer f.Close()

	_, err = io.CopyN(f, rand.Reader, OneGiB)
	return err
}
```

